"use client";

import { useId, useRef, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react";

import { IconChefHat, IconClock, IconFlame, IconIdea, IconUsers } from "@rhs-ui/icons";
import { AspectRatio } from "@rhs-ui/primitives/aspect-ratio";
import { DescriptionList, type DescriptionItem } from "@rhs-ui/primitives/description-list";
import { NumberInput } from "@rhs-ui/primitives/number-input";
import { cn } from "@/lib/utils";
import { KeepAwake } from "@rhs-ui/marketing/recipe-layout/keep-awake";
import { formatMinutes, showIngredient } from "@rhs-ui/marketing/recipe-layout/scale";
import { recipeJsonLdScript, type RecipeSchemaExtra } from "@rhs-ui/marketing/recipe-layout/schema";
import { StepTimer } from "@rhs-ui/marketing/recipe-layout/step-timer";
import type { RecipeIngredient, RecipeLabels, RecipeNutrition, RecipeStep, RecipeTimes } from "@rhs-ui/marketing/recipe-layout/types";

export type { RecipeIngredient, RecipeLabels, RecipeNutrition, RecipeStep, RecipeStepImage, RecipeStepTimer, RecipeTimes } from "@rhs-ui/marketing/recipe-layout/types";
export type { RecipeSchemaExtra } from "@rhs-ui/marketing/recipe-layout/schema";

export interface RecipeLayoutProps extends Omit<ComponentProps<"article">, "title"> {
  /** The recipe's name: "Slow-roasted tomato spaghetti". */
  title: string;
  /** A sentence or two on the dish. It is also the description in the Recipe data for search engines, so it is plain text. */
  intro?: string;
  /** A small line above the title: "Weeknight dinners". */
  eyebrow?: string;
  /** The main picture, under the intro. */
  image?: { src: string; alt: string };
  /** Prep, cook and total time in minutes. The total is worked out when it is left out. */
  times?: RecipeTimes;
  /** The number of servings the quantities are written for. */
  servings: number;
  /** The number of servings the page starts on, when it is not the one the recipe is written for. */
  defaultServings?: number;
  /** Called with the new number when the reader changes the servings. */
  onServingsChange?: (servings: number) => void;
  /** The ingredients for `servings`, in the order they are used. They are rescaled when the servings change. */
  ingredients: readonly RecipeIngredient[];
  /** The method, in order. Each step may have a picture and a timer. */
  steps: readonly RecipeStep[];
  /** Per serving. It does not change with the servings. */
  nutrition?: RecipeNutrition;
  /** Hints from the cook: how to keep it, what to swap. */
  tips?: readonly ReactNode[];
  /**
   * Writes the Recipe data for search engines into the page, made from these same props. Pass true, or an object
   * with the extra things search engines ask for: the picture's address, the author, the cuisine. Left out, nothing
   * is written; recipeJsonLd() in recipe-layout/schema gives you the same data to place yourself.
   */
  structuredData?: boolean | RecipeSchemaExtra;
  /** Offers a switch that keeps the screen on while cooking, where the browser can do it. On by default. */
  keepAwake?: boolean;
  /** The level of the title: 1 by default, because this is the page. Sections go one level below it. */
  headingLevel?: 1 | 2 | 3;
  /** Words for the fixed text, for a site that is not in English. */
  labels?: Partial<RecipeLabels>;
  /** Locale for numbers. */
  locale?: string;
}

const LABELS: RecipeLabels = {
  prep: "Prep",
  cook: "Cook",
  total: "Total",
  serves: "Serves",
  ingredients: "Ingredients",
  method: "Method",
  servings: "Servings",
  reset: "Back to {count}",
  announce: "Quantities updated for {count} servings.",
  keepAwake: "Keep screen awake",
  keepAwakeHint: "Stops the screen from dimming while you cook.",
  step: "Step",
  tips: "Tips",
  nutrition: "Nutrition",
  perServing: "Per serving",
  calories: "Calories",
  fat: "Fat",
  saturatedFat: "Saturated fat",
  carbohydrates: "Carbohydrates",
  sugars: "Sugars",
  fibre: "Fibre",
  protein: "Protein",
  sodium: "Sodium",
  pinch: "a pinch of",
  hour: "h",
  minute: "min",
  startTimer: "Start timer",
  pauseTimer: "Pause timer",
  resumeTimer: "Resume timer",
  resetTimer: "Reset timer",
  timeUp: "Time is up",
  timerStarted: "Timer started for {minutes} minutes.",
  timerDone: "Timer finished for step {step}.",
};

/** Consecutive ingredients that share a group are listed together under its heading. */
function groupsOf(ingredients: readonly RecipeIngredient[]): { title?: string; items: readonly RecipeIngredient[] }[] {
  const groups: { title?: string; items: RecipeIngredient[] }[] = [];
  for (const ingredient of ingredients) {
    const last = groups[groups.length - 1];
    if (last && last.title === ingredient.group) last.items.push(ingredient);
    else groups.push({ title: ingredient.group, items: [ingredient] });
  }
  return groups;
}

/**
 * A recipe page that cooks well: the times and the servings up front, the
 * ingredients beside the method on a wide screen (they stay in view while the
 * steps scroll past) and one after the other on a phone. A servings stepper
 * rescales every quantity, written the way a cook writes it (1½ tbsp, 750 g,
 * 1.2 kg) and announces the new count. Steps are an ordered list with large
 * numerals; a step may have a picture and a timer that counts down in place,
 * and where the browser can do it a switch keeps the screen on. The Recipe
 * data for search engines is made from the very same props, so the page and
 * its markup cannot disagree.
 */
export function RecipeLayout({
  title,
  intro,
  eyebrow,
  image,
  times,
  servings,
  defaultServings,
  onServingsChange,
  ingredients,
  steps,
  nutrition,
  tips = [],
  structuredData = false,
  keepAwake = true,
  headingLevel = 1,
  labels: custom,
  locale = "en-US",
  className,
  ...props
}: RecipeLayoutProps) {
  const labels = { ...LABELS, ...custom };
  const id = useId();
  const [count, setCount] = useState(Math.max(1, defaultServings ?? servings));
  const [announcement, setAnnouncement] = useState("");
  // Once the reader has changed the servings, an amount that changes lights up for a moment and settles.
  const [rescaled, setRescaled] = useState(false);
  const servingsField = useRef<HTMLInputElement>(null);
  const Title = `h${headingLevel}` as "h1" | "h2" | "h3";
  const Section = `h${headingLevel + 1}` as "h2" | "h3" | "h4";
  const Group = `h${headingLevel + 2}` as "h3" | "h4" | "h5";
  const number = new Intl.NumberFormat(locale);
  const factor = count / Math.max(1, servings);
  const words = { hour: labels.hour, minute: labels.minute };

  const total = times?.total ?? (times?.prep !== undefined || times?.cook !== undefined ? (times?.prep ?? 0) + (times?.cook ?? 0) : undefined);
  const facts: { label: string; value: string; icon: ReactNode }[] = [
    ...(times?.prep !== undefined ? [{ label: labels.prep, value: formatMinutes(times.prep, words, locale), icon: <IconChefHat /> }] : []),
    ...(times?.cook !== undefined ? [{ label: labels.cook, value: formatMinutes(times.cook, words, locale), icon: <IconFlame /> }] : []),
    ...(total !== undefined ? [{ label: labels.total, value: formatMinutes(total, words, locale), icon: <IconClock /> }] : []),
    { label: labels.serves, value: number.format(count), icon: <IconUsers /> },
  ];

  function change(next: number) {
    // The field reports its number whenever it is left, also when nothing was typed.
    if (next === count) return;
    setRescaled(true);
    setCount(next);
    onServingsChange?.(next);
    setAnnouncement(labels.announce.replace("{count}", number.format(next)));
  }

  function reset() {
    change(servings);
    // The button goes away as soon as the count is back, so focus moves to the field it belonged to, once the new number is in it.
    window.requestAnimationFrame(() => servingsField.current?.focus());
  }

  // The ingredients as they are written for this number of servings, grouped under their headings.
  const lines = groupsOf(ingredients).map((group) => ({
    title: group.title,
    items: group.items.map((ingredient) => {
      const shown = showIngredient(ingredient, factor, locale, labels.pinch);
      return { shown, written: [shown.amount, shown.unit].filter(Boolean).join(" ") };
    }),
  }));
  // The amount column fits the longest amount ("2½ handfuls") and is never narrower than 6.5rem, so no amount breaks over two lines and both groups line up.
  const longest = Math.max(0, ...lines.flatMap((group) => group.items.map((line) => line.written.length)));
  const amountColumn = { "--amount-width": `max(6.5rem, ${longest + 1}ch)` } as CSSProperties;

  const nutritionItems: DescriptionItem[] = [];
  const addNutrition = (term: string, value: number | undefined, unit: string) => {
    if (value !== undefined) nutritionItems.push({ term, value: `${number.format(value)} ${unit}` });
  };
  addNutrition(labels.calories, nutrition?.calories, "kcal");
  addNutrition(labels.fat, nutrition?.fat, "g");
  addNutrition(labels.saturatedFat, nutrition?.saturatedFat, "g");
  addNutrition(labels.carbohydrates, nutrition?.carbohydrates, "g");
  addNutrition(labels.sugars, nutrition?.sugars, "g");
  addNutrition(labels.fibre, nutrition?.fibre, "g");
  addNutrition(labels.protein, nutrition?.protein, "g");
  addNutrition(labels.sodium, nutrition?.sodium, "mg");

  const timerWords = { start: labels.startTimer, pause: labels.pauseTimer, resume: labels.resumeTimer, reset: labels.resetTimer, timeUp: labels.timeUp, started: labels.timerStarted, done: labels.timerDone };
  let lineNumber = 0;

  return (
    <article data-slot="recipe-layout" className={cn("w-full break-words", className)} {...props}>
      <header className="max-w-3xl">
        {eyebrow ? <p className="mb-4 text-xs font-medium tracking-[0.18em] text-muted-foreground uppercase">{eyebrow}</p> : null}
        <Title className="text-4xl leading-[1.06] font-medium tracking-[-0.045em] text-balance sm:text-5xl">{title}</Title>
        {intro ? <p className="mt-5 text-lg leading-relaxed text-pretty text-muted-foreground">{intro}</p> : null}
      </header>

      {image ? (
        <figure className="mt-8">
          {/* Taller on a phone, where a wide banner would shrink the dish to nothing. */}
          <div className="aspect-video overflow-hidden rounded-2xl border border-border bg-muted sm:aspect-[21/9]">
            {/* eslint-disable-next-line @next/next/no-img-element -- framework-neutral */}
            <img src={image.src} alt={image.alt} decoding="async" className="size-full object-cover" />
          </div>
        </figure>
      ) : null}

      {/* Two by two until 768px: four facts in a row need the room, or "1 h 10 min" breaks over two lines. */}
      <dl className="mt-8 grid grid-cols-2 overflow-hidden rounded-2xl border border-border bg-card md:grid-flow-col md:auto-cols-fr">
        {facts.map((fact, index) => (
          <div key={fact.label} className={cn("relative min-w-0 border-border py-3.5 pr-3.5 pl-[3.625rem] sm:py-4 sm:pr-5 sm:pl-[4.375rem]", index % 2 === 1 && "border-l md:border-l-0", index >= 2 && "border-t md:border-t-0", index > 0 && "md:border-l")}>
            <dt className="text-xs text-muted-foreground">
              <span aria-hidden="true" className="absolute top-1/2 left-3.5 grid size-8 -translate-y-1/2 place-items-center rounded-full bg-muted text-foreground sm:left-5 sm:size-9 [&_svg]:size-4 sm:[&_svg]:size-[1.125rem]">
                {fact.icon}
              </span>
              {fact.label}
            </dt>
            <dd className="mt-0.5 text-sm font-medium whitespace-nowrap tabular-nums">{fact.value}</dd>
          </div>
        ))}
      </dl>

      <div className="mt-12 grid gap-x-14 gap-y-12 lg:grid-cols-[minmax(0,21rem)_minmax(0,1fr)]">
        <section aria-labelledby={`${id}-ingredients`} className="relative lg:sticky lg:top-8 lg:max-h-[calc(100svh-4rem)] lg:self-start lg:overflow-y-auto">
          <div className="rounded-2xl border border-border bg-card p-5 sm:p-6">
            <Section id={`${id}-ingredients`} className="text-xl leading-tight font-semibold tracking-[-0.03em]">
              {labels.ingredients}
            </Section>
            <div className="mt-4 flex flex-wrap items-center gap-x-3 gap-y-2 rounded-xl bg-muted/60 p-3">
              <span id={`${id}-servings`} className="text-sm font-medium">
                {labels.servings}
              </span>
              <NumberInput ref={servingsField} value={count} min={1} max={99} onValueChange={change} aria-labelledby={`${id}-servings`} className="w-32 bg-background" />
              {count !== servings ? (
                <button
                  type="button"
                  onClick={reset}
                  className="rounded-sm text-[0.8125rem] text-muted-foreground underline decoration-foreground/30 underline-offset-4 outline-none transition-colors duration-150 hover:text-foreground hover:decoration-current focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none"
                >
                  {labels.reset.replace("{count}", number.format(servings))}
                </button>
              ) : null}
            </div>
            <p role="status" className="sr-only">
              {announcement}
            </p>
            <div style={amountColumn} className="mt-3 grid gap-5">
              {lines.map((group, groupIndex) => (
                <div key={`${group.title ?? "list"}-${groupIndex}`}>
                  {group.title ? <Group className="mb-1 pt-3 text-xs font-medium tracking-[0.14em] text-muted-foreground uppercase">{group.title}</Group> : null}
                  <ul role="list" className="divide-y divide-border">
                    {group.items.map(({ shown, written }) => {
                      lineNumber += 1;
                      return (
                        <li key={lineNumber} className="grid grid-cols-[var(--amount-width)_minmax(0,1fr)] gap-x-3 py-2.5 text-[0.9375rem] leading-snug">
                          {/* The key follows the text, so only an amount that changed starts again and lights up. */}
                          <span key={written} className={cn("self-start font-medium whitespace-nowrap tabular-nums", rescaled && "-mx-1 w-fit rounded-sm bg-transparent px-1 transition-colors duration-700 motion-reduce:transition-none starting:bg-foreground/15")}>
                            {written}
                          </span>
                          <span className="min-w-0">
                            {shown.name}
                            {shown.note ? <span className="text-muted-foreground">, {shown.note}</span> : null}
                          </span>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              ))}
            </div>
          </div>
        </section>

        <div className="grid min-w-0 content-start gap-12">
          <section aria-labelledby={`${id}-method`}>
            <div className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3">
              <Section id={`${id}-method`} className="text-xl leading-tight font-semibold tracking-[-0.03em]">
                {labels.method}
              </Section>
              {keepAwake ? <KeepAwake label={labels.keepAwake} hint={labels.keepAwakeHint} /> : null}
            </div>
            <ol role="list" className="mt-4 divide-y divide-border border-y border-border">
              {steps.map((step, index) => {
                const position = index + 1;
                return (
                  <li key={position} id={`${id}-step-${position}`} className="grid scroll-mt-24 gap-x-6 gap-y-2 py-7 sm:grid-cols-[3.75rem_minmax(0,1fr)]">
                    <span aria-hidden="true" className="text-4xl leading-none font-medium tracking-[-0.06em] text-muted-foreground/70 tabular-nums sm:text-5xl">
                      {position}
                    </span>
                    <div className="min-w-0">
                      <p className="text-base leading-relaxed sm:text-[1.0625rem]">
                        <span className="sr-only">
                          {labels.step} {position}:{" "}
                        </span>
                        {step.text}
                      </p>
                      {step.image ? (
                        <figure className="mt-5">
                          <AspectRatio ratio={16 / 10} className="overflow-hidden rounded-xl border border-border bg-muted">
                            {/* eslint-disable-next-line @next/next/no-img-element -- framework-neutral */}
                            <img src={step.image.src} alt={step.image.alt} loading="lazy" decoding="async" className="size-full object-cover" />
                          </AspectRatio>
                          {step.image.caption ? <figcaption className="mt-2.5 text-sm text-muted-foreground">{step.image.caption}</figcaption> : null}
                        </figure>
                      ) : null}
                      {step.timer ? <StepTimer className="mt-4" minutes={step.timer.minutes} label={step.timer.label} step={position} labels={timerWords} /> : null}
                    </div>
                  </li>
                );
              })}
            </ol>
          </section>

          {tips.length || nutritionItems.length ? (
            <div className="grid items-start gap-5 md:grid-cols-2">
              {tips.length ? (
                <section aria-labelledby={`${id}-tips`} className="rounded-2xl border border-border bg-muted/40 p-5 sm:p-6">
                  <Section id={`${id}-tips`} className="flex items-center gap-2.5 text-base leading-tight font-semibold tracking-[-0.02em]">
                    <IconIdea aria-hidden="true" className="size-[1.125rem]" />
                    {labels.tips}
                  </Section>
                  <ul role="list" className="mt-4 grid gap-3">
                    {tips.map((tip, index) => (
                      <li key={index} className="flex gap-3 text-sm leading-relaxed text-foreground/90">
                        <span aria-hidden="true" className="mt-[0.5625rem] size-1.5 shrink-0 rounded-full bg-muted-foreground" />
                        <span className="min-w-0">{tip}</span>
                      </li>
                    ))}
                  </ul>
                </section>
              ) : null}
              {nutritionItems.length ? (
                <section aria-labelledby={`${id}-nutrition`} className="rounded-2xl border border-border bg-card p-5 sm:p-6">
                  <Section id={`${id}-nutrition`} className="text-base leading-tight font-semibold tracking-[-0.02em]">
                    {labels.nutrition}
                  </Section>
                  <p className="mt-1 text-xs text-muted-foreground">{labels.perServing}</p>
                  <DescriptionList items={nutritionItems} className="mt-4 [&_dd]:tabular-nums" />
                </section>
              ) : null}
            </div>
          ) : null}
        </div>
      </div>

      {structuredData ? (
        <script
          type="application/ld+json"
          // The text is JSON with its < escaped, so nothing in the recipe can close the script.
          dangerouslySetInnerHTML={{
            __html: recipeJsonLdScript(
              { title, intro, times, servings, ingredients, steps, nutrition },
              { image: image?.src, ...(typeof structuredData === "object" ? structuredData : {}) },
              locale,
            ),
          }}
        />
      ) : null}
    </article>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Label } from "@rhs-ui/primitives/label";
import { Switch } from "@rhs-ui/primitives/switch";
import { cn } from "@/lib/utils";

/** The part of a held screen wake lock this switch uses. */
interface WakeLockHold {
  release(): Promise<void>;
  addEventListener(type: "release", listener: () => void): void;
}

interface WakeLockSource {
  request(type: "screen"): Promise<WakeLockHold>;
}

export interface KeepAwakeProps {
  /** The switch's label: "Keep screen awake". */
  label: string;
  /** A line under it on why you would. */
  hint?: string;
  /** Said when the browser refuses the lock: "Your browser would not keep the screen on." */
  refusal?: string;
  className?: string;
}

/**
 * A switch that keeps the screen on while you cook, using the Wake Lock API.
 * It exists only where the browser has the API: the server and the first
 * render show nothing, and a browser without it never shows a switch that
 * cannot work. It asks for the lock when turned on, asks again when the tab
 * comes back (browsers let go of it while a tab is hidden), and lets go when
 * turned off or when the page goes. If the browser refuses, for example on a
 * low battery, the switch goes back to off.
 */
export function KeepAwake({ label, hint, refusal = "Your browser would not keep the screen on. Battery saver can block it.", className }: KeepAwakeProps) {
  const id = useId();
  const [supported, setSupported] = useState(false);
  const [on, setOn] = useState(false);
  const [refused, setRefused] = useState(false);
  const hold = useRef<WakeLockHold | null>(null);
  const wanted = useRef(false);

  const source = (): WakeLockSource | undefined => (navigator as unknown as { wakeLock?: WakeLockSource }).wakeLock;

  async function acquire() {
    try {
      const held = await source()?.request("screen");
      if (!held) throw new Error("No Wake Lock API.");
      // The cook may have switched it off, or left, while the browser was thinking.
      if (!wanted.current) {
        void held.release().catch(() => undefined);
        return;
      }
      hold.current = held;
      held.addEventListener("release", () => {
        if (hold.current === held) hold.current = null;
      });
    } catch {
      wanted.current = false;
      setOn(false);
      setRefused(true);
    }
  }

  async function release() {
    const held = hold.current;
    hold.current = null;
    await held?.release().catch(() => undefined);
  }

  useEffect(() => {
    setSupported(Boolean(source()));
    const back = () => {
      if (document.visibilityState === "visible" && wanted.current && !hold.current) void acquire();
    };
    document.addEventListener("visibilitychange", back);
    return () => {
      document.removeEventListener("visibilitychange", back);
      wanted.current = false;
      void release();
    };
  }, []);

  if (!supported) return null;

  return (
    <div data-slot="keep-awake" className={cn("flex items-start gap-3", className)}>
      <Switch
        id={id}
        checked={on}
        aria-describedby={hint ? `${id}-hint` : undefined}
        onCheckedChange={(next) => {
          setRefused(false);
          setOn(next);
          wanted.current = next;
          if (next) void acquire();
          else void release();
        }}
      />
      <div className="min-w-0">
        <Label htmlFor={id} className="h-6 text-sm">
          {label}
        </Label>
        {hint ? (
          <p id={`${id}-hint`} className="text-xs leading-snug text-muted-foreground">
            {hint}
          </p>
        ) : null}
        <p role="status" className={cn("text-xs leading-snug font-medium text-destructive", refused ? "mt-1" : "sr-only")}>
          {refused ? refusal : ""}
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { IconCheck, IconPause, IconPlay, IconRotateCcw, IconTimer } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";

export interface StepTimerLabels {
  start: string;
  pause: string;
  resume: string;
  reset: string;
  timeUp: string;
  /** Said once when it starts. {minutes} stands for the length. */
  started: string;
  /** Said once when it runs out. {step} stands for the step number. */
  done: string;
}

export interface StepTimerProps {
  /** How long to wait, in minutes. */
  minutes: number;
  /** The start button's text. The minutes by default. */
  label?: string;
  /** The number of the step the timer belongs to, for the message when it runs out. */
  step: number;
  /** Words for the buttons and the messages. */
  labels: StepTimerLabels;
  className?: string;
}

const pad = (value: number) => String(value).padStart(2, "0");

/** Seconds as a clock: 9:05, or 1:02:09 past an hour. */
function clock(seconds: number): string {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const rest = seconds % 60;
  return hours ? `${hours}:${pad(minutes)}:${pad(rest)}` : `${minutes}:${pad(rest)}`;
}

type Phase = "idle" | "running" | "paused" | "done";

/**
 * A timer for a step that has to be waited out. One press starts it, the clock
 * counts down in place with a quiet bar under it, and it can be paused and
 * reset. It counts against the clock rather than ticks, so a tab in the
 * background or a phone that sleeps for a moment cannot make it lose time.
 * Starting and finishing are announced once, the seconds are not. Start gives
 * way to Pause when it starts and Reset brings Start back, so focus is handed
 * on with the button and the keyboard keeps its place.
 */
export function StepTimer({ minutes, label, step, labels, className }: StepTimerProps) {
  const total = Math.max(1, Math.round(minutes * 60));
  const [phase, setPhase] = useState<Phase>("idle");
  const [left, setLeft] = useState(total);
  const [announcement, setAnnouncement] = useState("");
  const endsAt = useRef(0);
  const root = useRef<HTMLDivElement>(null);
  const startButton = useRef<HTMLButtonElement>(null);
  const pauseButton = useRef<HTMLButtonElement>(null);
  const resetButton = useRef<HTMLButtonElement>(null);
  /** Which control takes focus once the timer has changed shape, set only when the control that had focus is going away. */
  const handOver = useRef<"start" | "pause" | "reset" | null>(null);

  /** Focus only has to be handed on when it is on one of this timer's own buttons; it is never taken from anywhere else. */
  function keepFocus(next: "start" | "pause" | "reset") {
    if (root.current?.contains(document.activeElement)) handOver.current = next;
  }

  useEffect(() => {
    const next = handOver.current;
    handOver.current = null;
    if (next) ({ start: startButton, pause: pauseButton, reset: resetButton })[next].current?.focus();
  }, [phase]);

  useEffect(() => {
    if (phase !== "running") return;
    const tick = () => {
      const rest = Math.max(0, Math.ceil((endsAt.current - Date.now()) / 1000));
      setLeft(rest);
      if (rest === 0) {
        // The pause button goes when time is up and Reset is what is left, so focus on the one moves to the other.
        if (root.current?.contains(document.activeElement)) handOver.current = "reset";
        setPhase("done");
        setAnnouncement(labels.done.replace("{step}", String(step)));
      }
    };
    const timer = window.setInterval(tick, 250);
    tick();
    return () => window.clearInterval(timer);
  }, [phase, step, labels.done]);

  function start() {
    endsAt.current = Date.now() + left * 1000;
    keepFocus("pause");
    setPhase("running");
    setAnnouncement(labels.started.replace("{minutes}", String(minutes)));
  }

  /** The time spent paused is not counted: the clock goes on from the number that was showing. */
  function resume() {
    endsAt.current = Date.now() + left * 1000;
    setPhase("running");
  }

  function reset() {
    keepFocus("start");
    setLeft(total);
    setPhase("idle");
    setAnnouncement("");
  }

  const elapsed = Math.min(1, 1 - left / total);
  return (
    <div ref={root} data-slot="step-timer" data-phase={phase} className={cn("flex items-center gap-3", className)}>
      {phase === "idle" ? (
        <Button ref={startButton} type="button" variant="outline" size="sm" onClick={start}>
          <IconTimer aria-hidden="true" />
          {label ?? `${minutes} min`}
          <span className="sr-only"> ({labels.start})</span>
        </Button>
      ) : (
        <div className={cn("flex items-center gap-1 rounded-lg border bg-background py-1 pr-1 pl-3", phase === "done" ? "border-foreground" : "border-border")}>
          {phase === "done" ? (
            <span className="flex items-center gap-2 pr-1 text-sm font-medium">
              <IconCheck aria-hidden="true" className="size-4" strokeWidth={2.25} />
              {labels.timeUp}
            </span>
          ) : (
            <span role="timer" className="min-w-[3.25rem] pr-2 text-sm font-medium tabular-nums">
              {clock(left)}
            </span>
          )}
          {phase === "done" ? null : (
            <Button ref={pauseButton} type="button" variant="ghost" size="icon-sm" aria-label={phase === "running" ? labels.pause : labels.resume} onClick={phase === "running" ? () => setPhase("paused") : resume}>
              {phase === "running" ? <IconPause /> : <IconPlay />}
            </Button>
          )}
          <Button ref={resetButton} type="button" variant="ghost" size="icon-sm" aria-label={labels.reset} onClick={reset}>
            <IconRotateCcw />
          </Button>
        </div>
      )}
      {phase === "running" || phase === "paused" ? (
        <span aria-hidden="true" className="h-1 w-20 overflow-hidden rounded-full bg-muted">
          <span className="block h-full rounded-full bg-foreground transition-[width] duration-300 ease-linear motion-reduce:transition-none" style={{ width: `${Math.round(elapsed * 100)}%` }} />
        </span>
      ) : null}
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}

import type { RecipeIngredient } from "@rhs-ui/marketing/recipe-layout/types";

/**
 * Rescaling a quantity the way a cook writes it: fractions for spoons, cups
 * and counted things, decimals for metric weights and volumes, and a bigger
 * unit once the number gets big. It holds no hooks, so a Server Component can
 * use it to write the same lines the page shows.
 */

/** The fractions each kind of measure has, and a cook can read at a glance. */
const SPOON = [0, 1 / 8, 1 / 4, 1 / 3, 1 / 2, 2 / 3, 3 / 4, 1] as const;
const CUP = [0, 1 / 4, 1 / 3, 1 / 2, 2 / 3, 3 / 4, 1] as const;
const COUNT = [0, 1 / 4, 1 / 2, 3 / 4, 1] as const;

const GLYPHS: ReadonlyArray<readonly [number, string]> = [
  [1 / 8, "⅛"],
  [1 / 4, "¼"],
  [1 / 3, "⅓"],
  [1 / 2, "½"],
  [2 / 3, "⅔"],
  [3 / 4, "¾"],
];

/** Units written with a decimal rather than a fraction. */
const DECIMAL_UNITS = new Set(["g", "kg", "ml", "l", "cl", "dl", "mm", "cm"]);

/** A number as a whole and one of the fractions of its measure: 1.5 is "1½", 0.3 is "⅓". Null when it rounds to nothing. */
function toFraction(value: number, fractions: readonly number[]): { text: string; value: number } | null {
  if (!Number.isFinite(value) || value <= 0) return null;
  const whole = Math.floor(value + 1e-9);
  const rest = Math.max(0, value - whole);
  let best = fractions[0] ?? 0;
  for (const fraction of fractions) if (Math.abs(fraction - rest) < Math.abs(best - rest)) best = fraction;
  const carried = best === 1;
  const wholes = carried ? whole + 1 : whole;
  const glyph = carried ? "" : (GLYPHS.find(([fraction]) => Math.abs(fraction - best) < 1e-9)?.[1] ?? "");
  const text = `${wholes > 0 ? wholes : ""}${glyph}`;
  return text === "" ? null : { text, value: wholes + (carried ? 0 : best) };
}

/** Whole grams and millilitres to the nearest 5 from 20 up, to the nearest half below that. */
function roundMetric(value: number): number {
  return value >= 20 ? Math.round(value / 5) * 5 : Math.round(value * 2) / 2;
}

const isHalfMultiple = (value: number) => Math.abs(value * 2 - Math.round(value * 2)) < 1e-6;

export interface ScaledAmount {
  /** The number as it is written: "1½", "250", "0.75". Empty when the amount rounds to nothing. */
  text: string;
  /** The number the text stands for, to decide between one and many. */
  value: number;
  /** The unit after conversion: 1500 g is "1.5 kg". */
  unit: string | undefined;
}

/**
 * Scales a quantity by a factor and writes it with a sensible number and unit.
 * With `whole` the amount is a whole number of at least one: an egg is never ¾.
 */
export function scaleAmount(quantity: number, unit: string | undefined, factor: number, locale = "en-US", whole = false): ScaledAmount {
  let value = quantity * factor;
  if (whole) {
    const count = Math.max(1, Math.round(value));
    return { text: new Intl.NumberFormat(locale).format(count), value: count, unit };
  }
  let shown = unit;
  if (shown === "g" && value >= 1000) [value, shown] = [value / 1000, "kg"];
  else if (shown === "kg" && value < 1) [value, shown] = [value * 1000, "g"];
  else if (shown === "ml" && value >= 1000) [value, shown] = [value / 1000, "l"];
  else if (shown === "l" && value < 1) [value, shown] = [value * 1000, "ml"];
  else if (shown === "tsp" && value >= 3 && isHalfMultiple(value / 3)) [value, shown] = [value / 3, "tbsp"];
  else if (shown === "tbsp" && value < 1) [value, shown] = [value * 3, "tsp"];
  else if (shown === "cup" && value < 0.25) [value, shown] = [value * 16, "tbsp"];

  if (shown !== undefined && DECIMAL_UNITS.has(shown)) {
    // Past a kilogram or a litre, to the nearest 50 g or 50 ml: 1.13 kg is 1.15 kg.
    const number = shown === "kg" || shown === "l" ? Math.round(value * 20) / 20 : roundMetric(value);
    return { text: new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(number), value: number, unit: shown };
  }
  const fractions = shown === "tsp" || shown === "tbsp" ? SPOON : shown === "cup" ? CUP : COUNT;
  const fraction = toFraction(value, fractions);
  return { text: fraction?.text ?? "", value: fraction?.value ?? value, unit: shown };
}

export interface ShownIngredient {
  /** The amount: "1½", or a few words such as "a pinch of" when it rounds to nothing. Empty for a line without a quantity. */
  amount: string;
  /** The unit, in its plural form when the amount is more than one. */
  unit: string;
  name: string;
  note?: string;
}

/** An ingredient written for a number of servings, as a factor of the servings the recipe is written for. */
export function showIngredient(ingredient: RecipeIngredient, factor: number, locale = "en-US", pinch = "a pinch of"): ShownIngredient {
  if (ingredient.quantity === undefined) return { amount: "", unit: "", name: ingredient.name, note: ingredient.note };
  const scaled = scaleAmount(ingredient.quantity, ingredient.unit, factor, locale, ingredient.whole);
  const many = scaled.value > 1;
  const unit = scaled.unit === undefined ? "" : many && scaled.unit === ingredient.unit && ingredient.unitPlural ? ingredient.unitPlural : scaled.unit;
  const name = many && !unit && ingredient.plural ? ingredient.plural : ingredient.name;
  return { amount: scaled.text === "" ? pinch : scaled.text, unit: scaled.text === "" ? "" : unit, name, note: ingredient.note };
}

/** The same line as plain text, for search engines and for reading aloud: "1½ tbsp olive oil, plus extra to serve". */
export function ingredientLine(ingredient: RecipeIngredient, factor = 1, locale = "en-US", pinch = "a pinch of"): string {
  const shown = showIngredient(ingredient, factor, locale, pinch);
  const text = [shown.amount, shown.unit, shown.name].filter(Boolean).join(" ");
  return shown.note ? `${text}, ${shown.note}` : text;
}

/** Minutes as the cook says them: "15 min", "1 h 10 min". */
export function formatMinutes(minutes: number, words: { hour: string; minute: string }, locale = "en-US"): string {
  const total = Math.max(0, Math.round(minutes));
  const number = new Intl.NumberFormat(locale);
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  const parts: string[] = [];
  if (hours) parts.push(`${number.format(hours)} ${words.hour}`);
  if (rest || !hours) parts.push(`${number.format(rest)} ${words.minute}`);
  return parts.join(" ");
}

import { ingredientLine } from "@rhs-ui/marketing/recipe-layout/scale";
import type { RecipeIngredient, RecipeNutrition, RecipeStep, RecipeTimes } from "@rhs-ui/marketing/recipe-layout/types";

/** What the Recipe data is made from: the same props the layout takes. */
export interface RecipeSchemaInput {
  title: string;
  intro?: string;
  times?: RecipeTimes;
  /** The servings the recipe is written for. */
  servings: number;
  ingredients: readonly RecipeIngredient[];
  steps: readonly RecipeStep[];
  nutrition?: RecipeNutrition;
}

/** What search engines ask for that the page itself does not show. */
export interface RecipeSchemaExtra {
  /** Address of the main picture, or several. Google needs one to show a recipe in its results. */
  image?: string | readonly string[];
  /** Who wrote it. */
  author?: string;
  /** When it was published, as an ISO date. */
  datePublished?: string;
  /** "Italian". */
  cuisine?: string;
  /** "Main course". */
  category?: string;
  /** Words people search for, separated by commas. */
  keywords?: string;
}

/** Minutes as an ISO 8601 duration: 75 is "PT1H15M". */
export function isoDuration(minutes: number): string {
  const total = Math.max(0, Math.round(minutes));
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  return `PT${hours ? `${hours}H` : ""}${rest || !hours ? `${rest}M` : ""}`;
}

/**
 * The Recipe data for search engines (schema.org), made from the props of the
 * layout, so the page and its structured data cannot disagree. Ingredients are
 * written for the servings the recipe is written for, not for the number a
 * reader picked.
 */
export function recipeJsonLd(recipe: RecipeSchemaInput, extra: RecipeSchemaExtra = {}, locale = "en-US"): Record<string, unknown> {
  const { times, nutrition } = recipe;
  const total = times?.total ?? (times?.prep !== undefined || times?.cook !== undefined ? (times?.prep ?? 0) + (times?.cook ?? 0) : undefined);
  const data: Record<string, unknown> = {
    "@context": "https://schema.org",
    "@type": "Recipe",
    name: recipe.title,
    ...(recipe.intro ? { description: recipe.intro } : {}),
    ...(extra.image ? { image: extra.image } : {}),
    ...(extra.author ? { author: { "@type": "Person", name: extra.author } } : {}),
    ...(extra.datePublished ? { datePublished: extra.datePublished } : {}),
    ...(extra.cuisine ? { recipeCuisine: extra.cuisine } : {}),
    ...(extra.category ? { recipeCategory: extra.category } : {}),
    ...(extra.keywords ? { keywords: extra.keywords } : {}),
    ...(times?.prep !== undefined ? { prepTime: isoDuration(times.prep) } : {}),
    ...(times?.cook !== undefined ? { cookTime: isoDuration(times.cook) } : {}),
    ...(total !== undefined ? { totalTime: isoDuration(total) } : {}),
    recipeYield: `${recipe.servings} servings`,
    recipeIngredient: recipe.ingredients.map((ingredient) => ingredientLine(ingredient, 1, locale)),
    recipeInstructions: recipe.steps.map((step) => ({ "@type": "HowToStep", text: step.text, ...(step.image ? { image: step.image.src } : {}) })),
  };
  if (nutrition) {
    const grams = (value: number | undefined) => (value === undefined ? undefined : `${value} g`);
    data.nutrition = Object.fromEntries(
      Object.entries({
        "@type": "NutritionInformation",
        servingSize: "1 serving",
        calories: nutrition.calories === undefined ? undefined : `${nutrition.calories} calories`,
        fatContent: grams(nutrition.fat),
        saturatedFatContent: grams(nutrition.saturatedFat),
        carbohydrateContent: grams(nutrition.carbohydrates),
        sugarContent: grams(nutrition.sugars),
        fiberContent: grams(nutrition.fibre),
        proteinContent: grams(nutrition.protein),
        sodiumContent: nutrition.sodium === undefined ? undefined : `${nutrition.sodium} mg`,
      }).filter(([, value]) => value !== undefined),
    );
  }
  return data;
}

/** The Recipe data as the text of a script element. The < is escaped, so nothing in a title can close the script. */
export function recipeJsonLdScript(recipe: RecipeSchemaInput, extra: RecipeSchemaExtra = {}, locale = "en-US"): string {
  return JSON.stringify(recipeJsonLd(recipe, extra, locale)).replace(/</g, "\\u003c");
}

export interface RecipeIngredient {
  /** How much, for the number of servings the recipe is written for. Leave it out for "salt, to taste": a line without a quantity never scales. */
  quantity?: number;
  /** "g", "kg", "ml", "l", "tsp", "tbsp", "cup", or a counted unit such as "clove". Leave it out when the name counts itself: 2 eggs. */
  unit?: string;
  /** The unit when the amount is more than one: "cups", "cloves". Units such as g and tbsp need none. */
  unitPlural?: string;
  /** What it is: "spaghetti", "egg". */
  name: string;
  /** The name when the amount is more than one and there is no unit: "eggs". */
  plural?: string;
  /** Never a fraction: an egg is 1 or 2, never ¾. The amount is rounded to a whole number of at least one. */
  whole?: boolean;
  /** A note after the name: "finely chopped", "plus extra to serve". */
  note?: string;
  /** A heading for a stretch of the list ("For the sauce"): ingredients that follow each other with the same group share it. */
  group?: string;
}

export interface RecipeStepImage {
  src: string;
  /** What the picture shows, for someone who cannot see it. */
  alt: string;
  /** A line under the picture. */
  caption?: string;
}

export interface RecipeStepTimer {
  /** How long the step takes, in minutes. It becomes a timer the cook can start. */
  minutes: number;
  /** The button's text. The minutes by default: "12 min". */
  label?: string;
}

export interface RecipeStep {
  /** What to do, in a sentence or two of plain text. It is also what search engines read as the instruction. */
  text: string;
  /** A picture of the step. */
  image?: RecipeStepImage;
  /** A timer for a step that has to be waited out. */
  timer?: RecipeStepTimer;
}

/** All in minutes. The total is worked out from prep and cook when it is left out. */
export interface RecipeTimes {
  prep?: number;
  cook?: number;
  total?: number;
}

/** Per serving. Grams, except calories (kcal) and sodium (mg), which is how search engines read them. */
export interface RecipeNutrition {
  calories?: number;
  fat?: number;
  saturatedFat?: number;
  carbohydrates?: number;
  sugars?: number;
  fibre?: number;
  protein?: number;
  sodium?: number;
}

export interface RecipeLabels {
  /** The label of the prep time. */
  prep: string;
  /** The label of the cook time. */
  cook: string;
  /** The label of the total time. */
  total: string;
  /** The label of the number of servings in the facts strip. */
  serves: string;
  /** The title of the ingredients section. */
  ingredients: string;
  /** The title of the method section. */
  method: string;
  /** The accessible name of the stepper, and the word beside it. */
  servings: string;
  /** The button that goes back to the written servings. {count} stands for the number. */
  reset: string;
  /** Said once, out loud, after the servings change. {count} stands for the number. */
  announce: string;
  /** The label of the keep-awake switch. */
  keepAwake: string;
  /** A line under it on why you would. */
  keepAwakeHint: string;
  /** Read out before the text of each step: "Step 3". */
  step: string;
  /** The title of the tips. */
  tips: string;
  /** The title of the nutrition panel. */
  nutrition: string;
  /** Under the nutrition heading: what the numbers are for. */
  perServing: string;
  /** The label of the calories row. */
  calories: string;
  /** The label of the fat row. */
  fat: string;
  /** The label of the saturated fat row. */
  saturatedFat: string;
  /** The label of the carbohydrates row. */
  carbohydrates: string;
  /** The label of the sugars row. */
  sugars: string;
  /** The label of the fibre row. */
  fibre: string;
  /** The label of the protein row. */
  protein: string;
  /** The label of the sodium row. */
  sodium: string;
  /** In front of the name of a line whose amount rounds to nothing. */
  pinch: string;
  /** The unit of an hour in a time: "h". */
  hour: string;
  /** The unit of a minute in a time: "min". */
  minute: string;
  /** The accessible name of the button that starts a timer. */
  startTimer: string;
  /** The accessible name of the button that pauses a timer. */
  pauseTimer: string;
  /** The accessible name of the button that resumes a timer. */
  resumeTimer: string;
  /** The accessible name of the button that resets a timer. */
  resetTimer: string;
  /** What a timer says when it runs out. */
  timeUp: string;
  /** Read out when a timer starts. {minutes} stands for the length. */
  timerStarted: string;
  /** Read out when a timer runs out. {step} stands for the number of the step. */
  timerDone: string;
}
